def _c(s): return re.sub(r'\s+', ' ', s).strip()
def _H(bl, text, start=0):
    for i in range(start, len(bl)):
        if bl[i][0] == 'h' and _c(bl[i][2]) == text: return i
    raise KeyError(text)
def _qs(bl, a, b): return [i for i in range(a, b) if bl[i][0] == 'p' and re.match(r'Q\.\d*\)', bl[i][2])]
def _q(bl, a, b, key):
    """start index of the PYQ in [a,b) whose own text (up to the next Q) matches key"""
    st = _qs(bl, a, b)
    for n, i in enumerate(st):
        end = st[n + 1] if n + 1 < len(st) else b
        if re.search(key, _c(' '.join(bl[j][2] for j in range(i, end)))): return i
    raise KeyError(key)
def _marks(bl):
    M = {}; s = 0
    for k, t in (('ag', '1 · AGRICULTURE'), ('ts', 'Types of Farming in India'), ('cr', 'Important Crops across the World'), ('sri', 'System of Rice Intensification'), ('sug', 'The shift of sugarcane industry to the South'), ('rev', 'Agriculture Revolutions in India'), ('reg', 'Agricultural Regions of the World'), ('term', 'Agricultural Terminologies'), ('nat', 'Natural Farming'), ('lu', 'Land Use Categories of India'), ('pyq1', 'PYQ'),
                 ('res', '2 · WORLD RESOURCES'), ('mine', 'Mining:'), ('lime', 'Limestone'), ('ores', 'Some Important Ores and their Products'), ('coal', 'Coal'), ('shale', 'Shale Oil And Gas'), ('nonc', 'Non-Conventional Energy Resources'), ('nuc', 'Nuclear Energy'), ('pyq2', '3 · PYQ'),
                 ('ind', '4 · INDUSTRIES'), ('typ', 'Types of Industries:'), ('loc', 'Factors Affecting the Location of Industries:'), ('wreg', 'Important Industrial Regions of the World'), ('ireg', 'Important Industrial Regions of India'),
                 ('tc', '5 · TRANSPORT AND COMMUNICATION'), ('road', 'Roadways'), ('rail', 'Railways'), ('pipe', 'Pipelines'), ('rope', 'Ropeways'), ('wt', '7 · WATER TRANSPORT'), ('inl', 'Inland Waterways'), ('ocean', 'Open Ocean Transport'), ('air', '8 · AIR TRANSPORT'), ('com', '9 · COMMUNICATION'), ('pyq3', '10 · PYQ'), ('rec', 'Recall sheet')):
        M[k] = _H(bl, t, s); s = M[k]
    M['minfig'] = next(i for i in range(M['mine'], len(bl)) if bl[i][0] == 'fig')
    A = (M['pyq1'], M['res']); R = (M['pyq2'], M['ind']); T = (M['pyq3'], M['rec'])
    for k, key in (('q_micro', 'micro-irrigation'), ('q_gang', 'lower Gangetic'), ('q_state', 'A state in India has'), ('q_salin', 'Salinization occurs'), ('q_mixed', 'mixed farming'), ('q_rain', 'Sesamum'), ('q_kharif', 'Which of these are Kharif'), ('q_kinn', 'Kinnaur'), ('q_maize', 'Maize can be used'), ('q_nitro', 'nitrogenous fertilisers'), ('q_ca', 'Conservation Agriculture'), ('q_soil', 'agricultural soils, consider'), ('q_noxide', 'release nitrogen oxides'), ('q_perm', 'permaculture'), ('q_palm', 'palm oil'), ('q_water', 'least water-efficient'), ('q_tea', 'tea-producing'), ('q_cocoa', 'cocoa producers'), ('q_turm', 'turmeric')):
        M[k] = _q(bl, *A, key)
    for k, key in (('r_coalimp', 'import millions of tonnes'), ('r_gond', 'Natural gas occurs in the Gondwana'), ('r_indcoal', 'characteristics of Indian coal'), ('r_shale', 'shale gas resources'), ('r_mines', 'auction non-coal mines'), ('r_monaz', 'Monazite is a source'), ('r_ilm', 'Ilmenite and rutile'), ('r_uran', 'despite having uranium'), ('r_ree', 'Rare Earth Elements')):
        M[k] = _q(bl, *R, key)
    for k, key in (('t_nh', r'Q\.1\)'), ('t_irs', 'Indian Remote Sensing'), ('t_port', r'Q\.3\)')):
        M[k] = _q(bl, *T, key)
    return M
def drop(bl):
    M = _marks(bl); d = set()
    for a, b in ((M['pyq1'], M['res']), (M['pyq2'], M['ind']), (M['pyq3'], M['rec'])):
        st = _qs(bl, a, b)
        for n, i in enumerate(st):
            end = st[n + 1] if n + 1 < len(st) else b
            ans = next(j for j in range(i, end) if bl[j][0] == 'p' and re.match(r'(Answer|Ans)\b', bl[j][2]))
            for j in range(i, ans + 1):
                if bl[j][0] in ('p', 'h', 'fig'): d.add(j)
        for j in range(a, b):
            t = _c(bl[j][2])
            if bl[j][0] == 'h' and (re.match(r'\(\w\)', t) or re.match(r'Statement \d', t) or t in ('PYQ', '3 · PYQ', '10 · PYQ')): d.add(j)
            if bl[j][0] == 'p' and t.startswith('Explanation'): d.add(j)
    return d
